import random
import string
from typing import List

# Generator for shell-like command line strings suitable for poptParseArgvString.
# We craft a variety of quoting/escaping patterns, options with/without values,
# positional args, empty args, and edge cases like nested quotes and backslashes.

MAX_LEN = 4096

_shell_words = [
    "run", "exec", "list", "update", "remove", "install", "--help", "-h",
    "--verbose", "-v", "--quiet", "-q", "--version", "--config", "-c",
    "--set", "--unset", "--flag", "--path", "--name", "--value",
    "--enable-feature", "--disable-feature",
]

_values = [
    "alpha", "beta", "gamma", "delta", "123", "0", "-1", "true", "false",
    "yes", "no", "maybe", "with spaces", "tabs\tinside", "new\nline",
    "quote'inner", 'dq"inner', r"back\\slash", "semi;colon", "comma,sep",
    "unicode-π", "emoji-🙂", "empty", "longvalue",
]

_path_frags = ["/usr/bin", "/etc/popt", "~/.config", "./relative", "../up", "/tmp/x", "/a/b/c"]

# Helpers to quote/escape values in various valid shell-like ways understood by poptParseArgvString.

def sh_escape_simple(s: str) -> str:
    # Use backslashes to escape spaces, tabs, quotes, and backslashes
    out = []
    for ch in s:
        if ch in " \t\n\\'\"":
            out.append("\\" + ch)
        else:
            out.append(ch)
    return "".join(out)


def sh_single_quote(s: str) -> str:
    # In POSIX shell, single quotes cannot be escaped inside single quotes; one way is to close/open around '
    # poptParseArgvString supports shell-like rules with backslash escaping; emulate robustly:
    if "'" not in s:
        return "'" + s + "'"
    # Split on ' and join using '\'' pattern
    parts = s.split("'")
    return "'" + "'\\''".join(parts) + "'"


def sh_double_quote(s: str) -> str:
    # Escape backslash, double quote, newline inside double quotes
    esc = s.replace("\\", r"\\\\").replace('"', r'\"').replace("\n", r"\n")
    return '"' + esc + '"'


def with_equals(opt: str, val: str, quote_style: str) -> str:
    if quote_style == "none":
        return f"{opt}={sh_escape_simple(val)}"
    if quote_style == "sq":
        return f"{opt}={sh_single_quote(val)}"
    if quote_style == "dq":
        return f"{opt}={sh_double_quote(val)}"
    return f"{opt}={val}"


def separate(opt: str, val: str, quote_style: str) -> List[str]:
    if quote_style == "none":
        return [opt, sh_escape_simple(val)]
    if quote_style == "sq":
        return [opt, sh_single_quote(val)]
    if quote_style == "dq":
        return [opt, sh_double_quote(val)]
    return [opt, val]


def random_word(rng: random.Random) -> str:
    # Mix of pre-defined words and random identifiers
    choice_pool = _shell_words + [
        "--opt" + str(rng.randint(0, 9)),
        "-" + rng.choice(string.ascii_letters),
        "pos" + str(rng.randint(0, 999)),
    ]
    return rng.choice(choice_pool)


def random_value(rng: random.Random) -> str:
    base = rng.choice(_values)
    # Occasionally enrich with path fragment or composed tokens
    if rng.random() < 0.5:
        base = base + rng.choice(["", "-", "/", "_"]) + rng.choice(_values + _path_frags)
    # Occasionally insert whitespace/newlines/tabs inside
    if rng.random() < 0.3:
        insert = rng.choice([" ", "\t", "\n"]) * rng.randint(1, 2)
        pos = rng.randint(0, len(base))
        base = base[:pos] + insert + base[pos:]
    return base


def build_command(rng: random.Random) -> str:
    parts: List[str] = []
    # Start with a plausible argv[0]
    prog = rng.choice(["prog", "tool", "app", "popt-tester", "cli"])
    parts.append(prog)

    # Add a mixture of options with and without arguments, and positionals
    n = rng.randint(3, 12)
    for _ in range(n):
        kind = rng.random()
        if kind < 0.25:
            # flag only
            parts.append(random_word(rng))
        elif kind < 0.60:
            # option with value via equals
            opt = rng.choice(["--config", "--set", "--name", "--value", "--path", "--define", "--opt"]) + (
                str(rng.randint(0, 3)) if rng.random() < 0.3 else ""
            )
            val = random_value(rng)
            quote_style = rng.choice(["none", "sq", "dq"])
            parts.append(with_equals(opt, val, quote_style))
        elif kind < 0.85:
            # option with separate value
            opt = rng.choice(["-c", "-o", "-f", "--file", "--output", "--name"]) 
            val = random_value(rng)
            quote_style = rng.choice(["none", "sq", "dq"])
            parts.extend(separate(opt, val, quote_style))
        else:
            # positional argument (possibly quoted)
            val = random_value(rng)
            style = rng.choice(["none", "sq", "dq"]) if any(ch in val for ch in " \t\n\"'\\") else "none"
            if style == "sq":
                parts.append(sh_single_quote(val))
            elif style == "dq":
                parts.append(sh_double_quote(val))
            else:
                parts.append(sh_escape_simple(val))

    # Occasionally inject empty argument using quotes or backslash-escaped space
    if rng.random() < 0.4:
        parts.insert(rng.randint(1, len(parts)), "''" if rng.random() < 0.5 else '""')
    if rng.random() < 0.3:
        parts.append("\\ ")  # backslash-space becomes a single space arg start/end combination
        # Make it a proper empty-like token by quoting around it sometimes
        if rng.random() < 0.5:
            parts[-1] = '"' + parts[-1] + '"'

    # Join with random spacing and escaped newlines
    sep_pieces = []
    for i, p in enumerate(parts):
        sep_pieces.append(p)
        if i != len(parts) - 1:
            # spacing: mix of spaces, tabs, newlines, and backslash-newline continuation
            choice = rng.random()
            if choice < 0.5:
                sep_pieces.append(" ")
            elif choice < 0.7:
                sep_pieces.append("\t")
            elif choice < 0.9:
                sep_pieces.append("\n")
            else:
                sep_pieces.append("\\\n")  # escaped newline should be trimmed/continued
    cmd = "".join(sep_pieces)

    # Ensure not exceeding MAX_LEN and end with newline sometimes
    if len(cmd) > MAX_LEN - 2:
        cmd = cmd[: MAX_LEN - 2]
    if rng.random() < 0.5:
        cmd += "\n"
    return cmd


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Create between 1 and 3 command lines separated by newlines to exercise multi-line parsing
    lines = [build_command(rng) for _ in range(rng.randint(1, 3))]
    # Sometimes include comments starting with # which typical shell would treat as comment.
    # poptParseArgvString ignores invalid constructs gracefully; include both comment and non-comment lines.
    if rng.random() < 0.4:
        lines.insert(1 if len(lines) > 1 else 0, sh_escape_simple("# not a comment if escaped") )
    payload = "\n".join(lines)
    if len(payload) > MAX_LEN:
        payload = payload[:MAX_LEN]
    return payload.encode("utf-8", errors="surrogatepass")
